import {COUNTRY_REFERENCE_REVIEW} from './country-review.js';
import {AXES} from './context.js';
import {describeAxisPosition,renderAxisSummary} from './axis-presentation.js';
import {COUNTRY_AXES,rankCountries,countryCatalog} from './countries.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const IDEOLOGY_COPY={
 socialdemocrata:{name:'Socialdemocracia',phrase:'Prefiero una economía con iniciativa privada, un Estado activo y derechos sociales que reduzcan las desigualdades.'},
 liberal:{name:'Liberalismo de mercado',phrase:'Prefiero más libertad para emprender, competir y elegir, con impuestos contenidos y apertura a los cambios sociales.'},
 conservadora:{name:'Conservadurismo de mercado',phrase:'Prefiero una economía con iniciativa privada y cambios prudentes que preserven las tradiciones sociales.'},
 socialconservadora:{name:'Conservadurismo social',phrase:'Prefiero protección social y un Estado presente en la economía, junto con valores familiares y sociales tradicionales.'},
 mixta:{name:'Pragmatismo',phrase:'Prefiero combinar mercado, regulación y políticas sociales según cada problema, sin una inclinación marcada hacia uno de esos polos.'}
};
export function ideologyDescription(model){return {...model,...IDEOLOGY_COPY[model.id]}}
export function percentageBadge(score,label='afinidad'){return `<div class="percentage-badge"><strong>${score}%</strong><span>${esc(label)}</span></div>`}
export function differenceCard(x){const a=AXES[x.axis],reference=describeAxisPosition(a,x.reference);return `<article class="axis-comparison">${renderAxisSummary(a,x.user,{inlineResult:true})}<p class="comparison-reference">Referencia: <strong>${esc(reference.label)}</strong><span class="sr-only">. ${esc(a.name)}: vos ${x.user}, referencia ${x.reference}</span></p></article>`}
export function renderDifferences(entity,details){return `<p>Comparación con <strong>${esc(entity.name)}</strong>. Tu opción aparece resaltada con su porcentaje.</p><h3>En qué coincidís más</h3><div class="difference-grid">${details.near.map(differenceCard).join('')}</div><h3>En qué te diferenciás más</h3><div class="difference-grid">${details.far.length?details.far.map(differenceCard).join(''):'<p>Los puntajes coinciden en los ejes comparados.</p>'}</div><a href="#comparar/${entity.id}">Ver los doce ejes y sus fuentes</a>`}
export function distinctivePriorities(profile,entities){
 const items=AXES.map((axis,i)=>{const known=entities.map(e=>e.profile[i]).filter(Number.isFinite).sort((a,b)=>a-b);if(!known.length)return null;const middle=Math.floor(known.length/2),median=known.length%2?known[middle]:(known[middle-1]+known[middle])/2;return {axis:i,user:profile[i],reference:median,gap:Math.abs(profile[i]-median)}}).filter(Boolean);
 const unusual=[...items].sort((a,b)=>b.gap-a.gap||a.axis-b.axis)[0],typical=[...items].sort((a,b)=>a.gap-b.gap||a.axis-b.axis)[0];
 return `<div class="distinctive-grid">${[[unusual,'Tu posición más distinta'],[typical,'Tu punto más cercano']].map(([x,label])=>`<article><p class="small">${label}</p>${renderAxisSummary(AXES[x.axis],x.user)}<p class="small">${x.gap===0?'Coincidís con la mediana.':`A ${x.gap} puntos de la mediana de las referencias.`}</p></article>`).join('')}</div>`;
}
export function renderCountryResults(profile,mode='current'){
 const ranked=rankCountries(profile,mode),catalog=countryCatalog(mode),scores=new Map(ranked.map(x=>[x.entity.id,x.score]));
 const card=x=>'<article class="country-match">'+(mode==='current'?'<img class="country-flag-image" src="flags/'+x.entity.id+'.svg" alt="Bandera de '+esc(x.entity.name)+'" width="110" height="75">':'<span class="country-era" aria-hidden="true">'+esc(x.entity.period.match(/\d{4}/)?.[0]||'')+'</span>')+'<div><h3>'+esc(x.entity.name)+'</h3><p>'+esc(x.entity.period)+'</p></div>'+percentageBadge(x.score)+'</article>';
 const tied=ranked.filter(x=>x.score===ranked[0]?.score).length;
 return '<p class="small country-coverage">'+ranked.length+' perfiles comparables de '+catalog.length+' entradas. Afinidad constitucional sobre Economía, Instituciones y Religión. Compara documentos fechados; no describe a sus habitantes ni al gobierno actual y no presupone que el texto siga vigente.</p>'+(mode==='current'?'<p class="small">Afganistán y Siria: perfiles actuales pendientes; sus constituciones anteriores se muestran únicamente en Histórico.</p>':'')+(ranked.length?card(ranked[0]):'<p>No hay perfiles comparables.</p>')+(tied>1?'<p class="small">'+tied+' países comparten el porcentaje más alto. Orden alfabético dentro del mismo porcentaje.</p>':'')+'<h3>También cerca de vos</h3><div class="country-nearby">'+ranked.slice(1,4).map(card).join('')+'</div><details><summary>Ver los '+catalog.length+' países y sus fuentes</summary><label>Buscar país<input id="country-search" type="search" placeholder="Nombre del país" autocomplete="off"></label><ul class="country-catalog">'+catalog.map(c=>'<li data-country-search="'+esc(c.name.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,''))+'"><div><span>'+esc(mode==='current'?c.flag||'':'')+' '+esc(c.name)+'</span><p class="small">'+esc(c.period||'')+'</p><p class="small">'+c.notes.map(esc).join(' ')+'</p><p class="small">'+COUNTRY_AXES.map(i=>esc(AXES[i].name)+': '+(Number.isFinite(c.profile[i])?c.profile[i]:'pendiente')).join(' · ')+'</p><p class="small">'+c.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a>').join(' · ')+(c.subsequentlyAmended?' · El proveedor indica reformas posteriores no incorporadas.':'')+'</p></div><strong>'+(scores.has(c.id)?scores.get(c.id)+'%':'Pendiente')+'</strong></li>').join('')+'</ul><p id="country-empty" hidden>No hay países con ese nombre en este catálogo.</p></details><details><summary>Revisión de países y referencia 12Axes</summary><p>'+esc(COUNTRY_REFERENCE_REVIEW.note)+'</p><p>Se verificó la separación de períodos de Afganistán y Siria. La revisión integral de políticas actuales y de todos los regímenes históricos sigue pendiente; los otros perfiles conservan su rúbrica documental.</p><a href="'+COUNTRY_REFERENCE_REVIEW.url+'" target="_blank" rel="noopener noreferrer">Consultar catálogo original de 12Axes</a></details><details><summary>Fuentes y criterio de afinidad</summary><p>Rúbrica documental editorial en tres ejes. Economía: 0 planificación y propiedad social, 25 dirección o provisión estatal, 50 propiedad con función social o esquema mixto, 75 protección de propiedad privada. Instituciones: 25 contrapesos, 50 Ejecutivo reforzado, 75 autoridad política dirigente, 100 soberano sin responsabilidad parlamentaria. Religión: 0 laicidad o no establecimiento, 25 garantía de libertad religiosa, 75 reconocimiento confesional especial, 100 religión estatal o jefatura confesional.</p><p>Afinidad = 100 menos la distancia absoluta media en esos tres ejes. Los nueve ejes no comparados permanecen sin puntaje. Las cifras son interpretaciones propias de disposiciones seleccionadas, no índices empíricos ni porcentajes publicados por las fuentes. Distintos textos pueden obtener el mismo perfil y empatar.</p><p>Las versiones enlazadas no constituyen una auditoría de vigencia jurídica en 2026. Esto importa especialmente en países con textos suspendidos, transiciones o conflictos. El período identifica el documento, no toda la historia ni todas las políticas del país. Las garantías escritas no prueban su aplicación real.</p><p>Catálogo actual: 193 miembros y dos observadores de la ONU. Nombres y banderas: <a href="https://github.com/mledoze/countries" target="_blank" rel="noopener noreferrer">mledoze/countries · ODbL</a>. No incluye todos los Estados con reconocimiento disputado. Referencias constitucionales: <a href="https://www.constituteproject.org/content/data" target="_blank" rel="noopener noreferrer">Constitute / Comparative Constitutions Project</a>, complementadas con fuentes oficiales identificadas en el catálogo. Selección histórica de documentos, sin pretensión de cubrir toda la historia.</p></details>';
}
